package com.craftdistrict.block;

import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

/** Generated by tools/generate_police_detention.py; decoration, part, facing. */
final class PoliceDetentionShapes {
    private static final VoxelShape[][][] SHAPES = {
        {
            rotations(Shapes.or(
                Block.box(0.75, 5.75, 1.5, 16, 8, 14.5),
                Block.box(0.75, 8, 2, 1.5, 9, 14),
                Block.box(2, 0, 2, 3.25, 5.75, 3.25),
                Block.box(2, 0, 12.75, 3.25, 5.75, 14)).optimize()),
            rotations(Shapes.or(
                Block.box(0, 5.75, 1.5, 15.25, 8, 14.5),
                Block.box(12.75, 0, 2, 14, 5.75, 3.25),
                Block.box(12.75, 0, 12.75, 14, 5.75, 14)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(4.5, 0, 3, 11.5, 2, 10.5),
                Block.box(3, 2, 1.5, 13, 4.75, 10.5),
                Block.box(3, 0, 10.5, 13, 13, 15.5),
                Block.box(7.5, 13, 12.5, 8.5, 15.625, 15.25)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(0, 0, 7.75, 16, 16, 8.25)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(0, 0, 15.375, 16, 16, 16)).optimize()),
            rotations(Shapes.or(
                Block.box(0, 0, 15.375, 16, 16, 16)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(2, 0, 7.25, 8.5, 14.75, 8.75),
                Block.box(7.5, 0, 7.25, 14.25, 14.75, 8.75),
                Block.box(7.25, 0, 7.5, 8.75, 14.75, 14.25),
                Block.box(7.375, 14.75, 7.375, 8.625, 16, 8.625)).optimize()),
            rotations(Shapes.or(
                Block.box(7.375, 0, 7.375, 8.625, 8.5, 8.625),
                Block.box(3.5, 8.5, 3.25, 13.25, 14.25, 10)).optimize())
        }
    };

    private PoliceDetentionShapes() { }

    static VoxelShape get(int decoration, int part, BlockState state) {
        int turn = switch (state.getValue(BlockStateProperties.HORIZONTAL_FACING)) {
            case EAST -> 1;
            case SOUTH -> 2;
            case WEST -> 3;
            default -> 0;
        };
        return SHAPES[decoration][part][turn];
    }

    private static VoxelShape[] rotations(VoxelShape north) {
        VoxelShape[] result = new VoxelShape[4];
        result[0] = north;
        for (int turn = 1; turn < 4; turn++) {
            VoxelShape rotated = Shapes.empty();
            for (AABB box : result[turn - 1].toAabbs()) {
                rotated = Shapes.or(rotated, Shapes.box(1 - box.maxZ, box.minY, box.minX,
                        1 - box.minZ, box.maxY, box.maxX));
            }
            result[turn] = rotated.optimize();
        }
        return result;
    }
}
